import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig({
  plugins: [vue()],
  server: {
    port: 5173,
    open: true
  }
})

/**
 * 火箭模型模块 — Class 架构
 *
 * 类层次:
 *   RocketComponent (base)
 *     ├── FirstStage   一级火箭 (body + ring + engine + fins)
 *     ├── SecondStage  二级火箭 (body + ring + engine)
 *     ├── Booster      助推器   (body + engine, 侧挂)
 *     ├── Fairing      整流罩   (body + tip)
 *     └── Payload      载荷     (sat body + solar panels)
 *   Engine             发动机   (engine cone + nozzle, 可带尾焰)
 *   Rocket             火箭整体 (组装所有部件)
 *
 * 所有部件共享 posHolder/orientProp 引用, 支持分离时切换位置属性 + 冻结朝向
 */

const Cesium = window.Cesium

// ─── 默认颜色 ───
const DEFAULT_COLORS = {
  body:     '#f0f0f0',
  ring:     '#1a1a2e',
  engine:   '#2a2a3e',
  engineChamber: '#3a3a4e',
  engineThroat:  '#1a1a2e',
  nozzle:   '#1a1a1a',
  turbopump: '#4a4a5e',
  fin:      '#3a3a4e',
  fairing:  '#e0e0e4',
  fairingTip: '#d0d0d8',
  satBody:  '#ffd633',
  satPanel: '#1e5bb8',
  booster:  '#aaaab0',
}

// ═══════════════════════════════════════════════
//  独立工具函数
// ═══════════════════════════════════════════════

/**
 * 创建火箭朝向属性 — Z 轴对齐速度方向
 */
export function createRocketOrientationProperty(posProp, getPitchFn) {
  return new Cesium.CallbackProperty((time) => {
    const pos = posProp.getValue(time)
    if (!pos) return undefined

    const dt = 0.5
    const tNext = Cesium.JulianDate.addSeconds(time, dt, new Cesium.JulianDate())
    const posNext = posProp.getValue(tNext)

    let dir
    if (posNext) {
      const vel = Cesium.Cartesian3.subtract(posNext, pos, new Cesium.Cartesian3())
      const velLen = Cesium.Cartesian3.magnitude(vel)
      if (velLen > 0.01) {
        dir = Cesium.Cartesian3.normalize(vel, new Cesium.Cartesian3())
      }
    }
    if (!dir) {
      dir = Cesium.Cartesian3.normalize(pos, new Cesium.Cartesian3())
    }

    let ref = new Cesium.Cartesian3(0, 0, 1)
    if (Math.abs(Cesium.Cartesian3.dot(dir, ref)) > 0.99) {
      ref = new Cesium.Cartesian3(1, 0, 0)
    }

    const xCol = Cesium.Cartesian3.normalize(
      Cesium.Cartesian3.cross(ref, dir, new Cesium.Cartesian3()),
      new Cesium.Cartesian3()
    )
    const yCol = Cesium.Cartesian3.cross(dir, xCol, new Cesium.Cartesian3())

    const rotMat = new Cesium.Matrix3(
      xCol.x, yCol.x, dir.x,
      xCol.y, yCol.y, dir.y,
      xCol.z, yCol.z, dir.z
    )
    return Cesium.Quaternion.fromRotationMatrix(rotMat, new Cesium.Quaternion())
  }, false)
}

/**
 * 从 store 配置计算各部件 Z 偏移
 */
export function computeZOffsets(rocketParts) {
  const findPart = (cat) => rocketParts.find(p => p.category === cat)
  let zCursor = 0
  const z = {}

  const fairingPart = findPart('fairing')
  if (fairingPart) {
    const d = fairingPart.dimensions
    const total = (d.bodyLength || 7) + (d.tipLength || 7)
    z.fairingTip = zCursor + total / 2 - (d.tipLength || 7) / 2
    z.fairingBody = z.fairingTip - (d.tipLength || 7) / 2 - (d.bodyLength || 7) / 2
    // 整流罩内部中心，载荷放这里
    z.satBody = z.fairingBody
    zCursor = z.fairingBody - (d.bodyLength || 7) / 2 - 2  // 整流罩和二级之间留间隙
  } else {
    const satPart = findPart('satellite')
    if (satPart) {
      z.satBody = zCursor + 3
      zCursor = z.satBody - (satPart.dimensions?.bodyZ || 3.5) / 2
    }
  }

  const stage2Part = findPart('stage2')
  if (stage2Part) {
    const d = stage2Part.dimensions
    const bl = d.bodyLength || 13, el = d.engineLength || 3, nl = d.nozzleLength || 2
    z.stage2Body = zCursor - bl / 2
    z.stage2Ring = z.stage2Body + bl / 2 - 1 - 1
    z.stage2Engine = z.stage2Body - bl / 2 - el / 2
    z.stage2Nozzle = z.stage2Engine - el / 2 - nl / 2
    zCursor = z.stage2Body - bl / 2
  }

  const stage1Part = findPart('stage1')
  if (stage1Part) {
    const d = stage1Part.dimensions
    const bl = d.bodyLength || 28, el = d.engineLength || 6, nl = d.nozzleLength || 3
    z.stage1Body = zCursor - bl / 2
    z.stage1Ring = z.stage1Body + bl / 2 - 1.5 - 1.5
    z.stage1Engine = z.stage1Body - bl / 2 - el / 2
    z.stage1Nozzle = z.stage1Engine - el / 2 - nl / 2
    z.fin = z.stage1Body - bl / 4
    zCursor = z.stage1Body - bl / 2
  }

  z.exhaust1 = z.stage1Body ? z.stage1Body - (stage1Part?.dimensions?.bodyLength || 40) / 2 - 1 : -21
  z.exhaust2 = z.stage2Body ? z.stage2Body - (stage2Part?.dimensions?.bodyLength || 20) / 2 - 1 : -11

  return z
}

// ═══════════════════════════════════════════════
//  RocketComponent 基类
// ═══════════════════════════════════════════════

class RocketComponent {
  /**
   * @param {Object}   opts
   * @param {Object}   opts.viewer       Cesium Viewer
   * @param {Object}   opts.posHolder    { prop: PositionProperty } 可切换引用
   * @param {Object}   opts.orientProp   朝向属性
   * @param {Object}   opts.config       部件配置 (dimensions, color, ...)
   * @param {Object}   opts.zOffsets     Z 偏移表
   */
  constructor({ viewer, posHolder, orientProp, config, zOffsets }) {
    this.viewer = viewer
    this.posHolder = posHolder
    this.orientProp = orientProp
    this.config = config || {}
    this.dimensions = this.config.dimensions || {}
    this.color = this.config.color || DEFAULT_COLORS.body
    this.zOffsets = zOffsets || {}
    this._entities = []
    this._visible = true
    this._frozenOrient = null
  }

  /** 子类实现 */
  build() { return this._entities }

  /** 显示所有实体 */
  show() {
    this._entities.forEach(e => { if (e) e.show = true })
    this._visible = true
  }

  /** 隐藏所有实体 */
  hide() {
    this._entities.forEach(e => { if (e) e.show = false })
    this._visible = false
  }

  /** 销毁所有实体 */
  destroy() {
    this._entities.forEach(e => { if (e) this.viewer.entities.remove(e) })
    this._entities = []
  }

  /** 冻结朝向 (分离时调用) */
  freezeOrientation(time) {
    const orient = this.orientProp.getValue(time)
    if (!orient) return
    this._frozenOrient = orient
    this._entities.forEach(e => {
      if (e) e.orientation = new Cesium.ConstantProperty(orient)
    })
  }

  /** 恢复动态朝向 (重置时调用) */
  restoreOrientation() {
    this._frozenOrient = null
    this._entities.forEach(e => {
      if (e) e.orientation = this.orientProp
    })
  }

  /** 切换位置属性 (分离时调用) */
  switchPosition(newPosProp) {
    this.posHolder.prop = newPosProp
  }

  get entities() { return this._entities }
  get visible() { return this._visible }

  // ─── protected helpers ───

  /** 创建子部件位置属性: 父位置 + 朝向旋转 × 本地偏移 */
  _createChildPos(offset) {
    const off = new Cesium.Cartesian3(offset[0], offset[1], offset[2])
    return new Cesium.CallbackProperty((time) => {
      const pos = this.posHolder.prop.getValue(time)
      if (!pos) return undefined
      const orient = this._frozenOrient || this.orientProp.getValue(time)
      if (!orient) return pos
      const rot = Cesium.Matrix3.fromQuaternion(orient, new Cesium.Matrix3())
      const worldOff = Cesium.Matrix3.multiplyByVector(rot, off, new Cesium.Cartesian3())
      return Cesium.Cartesian3.add(pos, worldOff, new Cesium.Cartesian3())
    }, false)
  }

  /** 创建带额外 Z 旋转的朝向 (用于尾翼) */
  _createRotatedOrient(zAngle) {
    const zQuat = Cesium.Quaternion.fromAxisAngle(
      Cesium.Cartesian3.UNIT_Z, zAngle, new Cesium.Quaternion()
    )
    return new Cesium.CallbackProperty((time) => {
      const orient = this._frozenOrient || this.orientProp.getValue(time)
      if (!orient) return undefined
      return Cesium.Quaternion.multiply(orient, zQuat, new Cesium.Quaternion())
    }, false)
  }
}

// ═══════════════════════════════════════════════
//  Engine 发动机 (燃烧室 + 收缩段 + 喉部 + 扩张喷管 + 涡轮泵)
// ═══════════════════════════════════════════════

class Engine {
  /**
   * @param {Object} opts
   * @param {Object} opts.viewer
   * @param {Object} opts.posHolder     同父级 posHolder
   * @param {Object} opts.orientProp    同父级 orientProp
   * @param {Object} opts.dimensions    { engineLength, engineTopR, engineBotR, nozzleLength, nozzleTopR, nozzleBotR }
   * @param {String} opts.color         发动机颜色
   * @param {Number} opts.engineZ       发动机 Z 偏移
   * @param {Number} opts.nozzleZ       喷管 Z 偏移
   */
  constructor({ viewer, posHolder, orientProp, dimensions, color, engineZ, nozzleZ, sideOffset }) {
    this.viewer = viewer
    this.posHolder = posHolder
    this.orientProp = orientProp
    this.dimensions = dimensions
    this.color = color || DEFAULT_COLORS.engine
    this.engineZ = engineZ
    this.nozzleZ = nozzleZ
    this.sideOffset = sideOffset || [0, 0]
    this._entities = []
    this._frozenOrient = null

    const self = this
    this._helper = {
      _createChildPos(offset) {
        const off = new Cesium.Cartesian3(
          offset[0] + self.sideOffset[0],
          offset[1] + self.sideOffset[1],
          offset[2]
        )
        return new Cesium.CallbackProperty((time) => {
          const pos = self.posHolder.prop.getValue(time)
          if (!pos) return undefined
          const orient = self._frozenOrient || self.orientProp.getValue(time)
          if (!orient) return pos
          const rot = Cesium.Matrix3.fromQuaternion(orient, new Cesium.Matrix3())
          const worldOff = Cesium.Matrix3.multiplyByVector(rot, off, new Cesium.Cartesian3())
          return Cesium.Cartesian3.add(pos, worldOff, new Cesium.Cartesian3())
        }, false)
      }
    }
  }

  build() {
    const d = this.dimensions
    const engineLen = d.engineLength || 6
    const engineTopR = d.engineTopR || 3.0
    const engineBotR = d.engineBotR || 1.0
    const nozzleLen = d.nozzleLength || 3
    const nozzleTopR = d.nozzleTopR || 1.0
    const nozzleBotR = d.nozzleBotR || 0.6

    const engineColor = Cesium.Color.fromCssColorString(this.color)

    // ── 发动机圆台 (上粗下细，紧贴级间段底部) ──
    this._entities.push(this.viewer.entities.add({
      position: this._helper._createChildPos([0, 0, this.engineZ]),
      orientation: this.orientProp,
      cylinder: {
        length: engineLen,
        topRadius: engineBotR,
        bottomRadius: engineTopR,
        material: engineColor,
        outline: false,
        numberOfVerticalLines: 0,
        slices: 48,
      },
    }))

    return this._entities
  }

  /** 尾焰发射器 Z 位置 (发动机底部) */
  get exhaustZ() {
    const d = this.dimensions
    return this.nozzleZ - (d.nozzleLength || 2) / 2 - 3
  }

  show() { this._entities.forEach(e => { if (e) e.show = true }) }
  hide() { this._entities.forEach(e => { if (e) e.show = false }) }

  destroy() {
    this._entities.forEach(e => { if (e) this.viewer.entities.remove(e) })
    this._entities = []
  }

  freezeOrientation(time) {
    const orient = this.orientProp.getValue(time)
    if (!orient) return
    this._frozenOrient = orient
    this._entities.forEach(e => {
      if (e) e.orientation = new Cesium.ConstantProperty(orient)
    })
  }

  restoreOrientation() {
    this._frozenOrient = null
    this._entities.forEach(e => {
      if (e) e.orientation = this.orientProp
    })
  }

  get entities() { return this._entities }
}

// ═══════════════════════════════════════════════
//  FirstStage 一级火箭
// ═══════════════════════════════════════════════

class FirstStage extends RocketComponent {
  constructor(opts) {
    super(opts)
    this.engine = null
  }

  build() {
    const d = this.dimensions
    const z = this.zOffsets
    const bodyColor = Cesium.Color.fromCssColorString(this.color)

    // 主体
    this._entities.push(this.viewer.entities.add({
      position: this._createChildPos([0, 0, z.stage1Body]),
      orientation: this.orientProp,
      cylinder: {
        length: d.bodyLength, topRadius: d.bodyRadius, bottomRadius: d.bodyRadius,
        material: bodyColor, outline: false, numberOfVerticalLines: 0, slices: 48,
      },
    }))

    // 级间环
    this._entities.push(this.viewer.entities.add({
      position: this._createChildPos([0, 0, z.stage1Ring]),
      orientation: this.orientProp,
      cylinder: {
        length: d.ringLength, topRadius: d.ringRadius, bottomRadius: d.ringRadius,
        material: Cesium.Color.fromCssColorString(DEFAULT_COLORS.ring),
        outline: false, numberOfVerticalLines: 0, slices: 48,
      },
    }))

    // 发动机
    this.engine = new Engine({
      viewer: this.viewer,
      posHolder: this.posHolder,
      orientProp: this.orientProp,
      dimensions: d,
      color: DEFAULT_COLORS.engine,
      engineZ: z.stage1Engine,
      nozzleZ: z.stage1Nozzle,
    })
    this.engine.build()
    this._entities.push(...this.engine.entities)

    return this._entities
  }

  get exhaustZ() { return this.engine ? this.engine.exhaustZ : this.zOffsets.exhaust1 }

  freezeOrientation(time) {
    super.freezeOrientation(time)
    if (this.engine) this.engine.freezeOrientation(time)
  }

  restoreOrientation() {
    super.restoreOrientation()
    if (this.engine) this.engine.restoreOrientation()
  }

  destroy() {
    super.destroy()
    if (this.engine) this.engine.destroy()
  }
}

