// ═══════════════════════════════════════════════
//  Booster 助推器 (侧挂)
// ═══════════════════════════════════════════════

class Booster extends RocketComponent {
  /**
   * @param {Object} opts
   * @param {Number} opts.sideAngle   侧挂角度 (弧度)
   * @param {Number} opts.parentRadius 父级半径 (一级主体)
   * @param {Number} opts.zBase        Z 基准 (与一级底部对齐)
   */
  constructor(opts) {
    super(opts)
    this.sideAngle = opts.sideAngle || 0
    this.parentRadius = opts.parentRadius || 3.5
    this.zBase = opts.zBase || 0
    this.engine = null
  }

  build() {
    const d = this.dimensions
    const bodyColor = Cesium.Color.fromCssColorString(this.color)
    const radial = this.parentRadius + d.bodyRadius + 0.5
    this.sideX = Math.cos(this.sideAngle) * radial
    this.sideY = Math.sin(this.sideAngle) * radial
    const sideX = this.sideX
    const sideY = this.sideY
    const bodyZ = this.zBase

    // 主体
    this._entities.push(this.viewer.entities.add({
      position: this._createChildPos([sideX, sideY, bodyZ]),
      orientation: this.orientProp,
      cylinder: {
        length: d.bodyLength, topRadius: d.bodyRadius, bottomRadius: d.bodyRadius,
        material: bodyColor, outline: false, numberOfVerticalLines: 0, slices: 48,
      },
    }))

    // 级间环 (从主体顶部向下偏移)
    const ringLen = 1
    const ringZ = bodyZ + d.bodyLength / 2 - ringLen / 2 - 1
    this._entities.push(this.viewer.entities.add({
      position: this._createChildPos([sideX, sideY, ringZ]),
      orientation: this.orientProp,
      cylinder: {
        length: ringLen, topRadius: d.bodyRadius + 0.1, bottomRadius: d.bodyRadius + 0.1,
        material: Cesium.Color.fromCssColorString(DEFAULT_COLORS.ring),
        outline: false, numberOfVerticalLines: 0, slices: 48,
      },
    }))

    // 发动机 (紧贴主体底部，侧挂在助推器位置)
    const engineLen = d.engineLength || 4
    const engineZ = bodyZ - d.bodyLength / 2 - engineLen / 2
    const nozzleZ = engineZ - engineLen / 2 - (d.nozzleLength || 2) / 2
    this.engine = new Engine({
      viewer: this.viewer,
      posHolder: this.posHolder,
      orientProp: this.orientProp,
      dimensions: {
        engineLength: engineLen, engineTopR: d.engineTopR || 1.5, engineBotR: d.engineBotR || 0.5,
        nozzleLength: d.nozzleLength || 2, nozzleTopR: d.nozzleTopR || 0.5, nozzleBotR: d.nozzleBotR || 0.3,
      },
      color: DEFAULT_COLORS.engine,
      engineZ,
      nozzleZ,
      sideOffset: [sideX, sideY],
    })
    this.engine.build()
    this._entities.push(...this.engine.entities)

    return this._entities
  }

  get exhaustZ() {
    return this.engine ? this.engine.exhaustZ : this.zBase - this.dimensions.bodyLength - 3
  }

  freezeOrientation(time) {
    super.freezeOrientation(time)
    if (this.engine) this.engine.freezeOrientation(time)
  }

  restoreOrientation() {
    super.restoreOrientation()
    if (this.engine) this.engine.restoreOrientation()
  }

  destroy() {
    super.destroy()
    if (this.engine) this.engine.destroy()
  }
}

// ═══════════════════════════════════════════════
//  Fairing 整流罩
// ═══════════════════════════════════════════════

class Fairing extends RocketComponent {
  build() {
    const d = this.dimensions
    const z = this.zOffsets
    const color = Cesium.Color.fromCssColorString(this.color)

    // 罩体
    this._entities.push(this.viewer.entities.add({
      position: this._createChildPos([0, 0, z.fairingBody]),
      orientation: this.orientProp,
      cylinder: {
        length: d.bodyLength, topRadius: d.bodyTopRadius, bottomRadius: d.bottomRadius,
        material: color, outline: false, numberOfVerticalLines: 0, slices: 48,
      },
    }))

    // 尖端
    this._entities.push(this.viewer.entities.add({
      position: this._createChildPos([0, 0, z.fairingTip]),
      orientation: this.orientProp,
      cone: {
        length: d.tipLength, topRadius: 0, bottomRadius: d.bottomRadius,
        material: Cesium.Color.fromCssColorString(DEFAULT_COLORS.fairingTip),
        outline: false, slices: 48,
      },
    }))

    return this._entities
  }
}

// ═══════════════════════════════════════════════
//  Payload 载荷 (卫星)
// ═══════════════════════════════════════════════

class Payload extends RocketComponent {
  constructor(opts) {
    super(opts)
    this._panels = []
    this._panelsDeployed = false
  }

  build() {
    const d = this.dimensions
    const z = this.zOffsets
    const color = Cesium.Color.fromCssColorString(this.color)

    // 卫星主体 (默认隐藏在整流罩内)
    this._entities.push(this.viewer.entities.add({
      show: false,
      position: this._createChildPos([0, 0, z.satBody]),
      orientation: this.orientProp,
      box: {
        dimensions: new Cesium.Cartesian3(d.bodyX, d.bodyY, d.bodyZ),
        material: color, outline: false,
      },
    }))

    // 左太阳能板
    this._panels.push(this.viewer.entities.add({
      show: false,
      position: this._createChildPos([-d.panelOff, 0, z.satBody]),
      orientation: this.orientProp,
      box: {
        dimensions: new Cesium.Cartesian3(d.panelX, d.panelY, d.panelZ),
        material: Cesium.Color.fromCssColorString(DEFAULT_COLORS.satPanel), outline: false,
      },
    }))

    // 右太阳能板
    this._panels.push(this.viewer.entities.add({
      show: false,
      position: this._createChildPos([d.panelOff, 0, z.satBody]),
      orientation: this.orientProp,
      box: {
        dimensions: new Cesium.Cartesian3(d.panelX, d.panelY, d.panelZ),
        material: Cesium.Color.fromCssColorString(DEFAULT_COLORS.satPanel), outline: false,
      },
    }))

    return this._entities
  }

  /** 显示卫星主体 */
  showBody() {
    this._entities.forEach(e => { if (e) e.show = true })
  }

  /** 展开太阳能板 */
  deployPanels() {
    this._panels.forEach(p => { if (p) p.show = true })
    this._panelsDeployed = true
  }

  /** 收回太阳能板 (重置) */
  retractPanels() {
    this._panels.forEach(p => { if (p) p.show = false })
    this._panelsDeployed = false
  }

  /** 隐藏主体 */
  hideBody() {
    this._entities.forEach(e => { if (e) e.show = false })
  }

  get panelsDeployed() { return this._panelsDeployed }

  destroy() {
    super.destroy()
    this._panels.forEach(e => { if (e) this.viewer.entities.remove(e) })
    this._panels = []
  }
}

// ═══════════════════════════════════════════════
//  Rocket 火箭整体 (组装器)
// ═══════════════════════════════════════════════

class Rocket {
  /**
   * @param {Object} opts
   * @param {Object} opts.viewer       Cesium Viewer
   * @param {Array}  opts.rocketParts  store 中的部件配置数组
   */
  constructor({ viewer, rocketParts }) {
    this.viewer = viewer
    this.rocketParts = rocketParts
    this.zOffsets = computeZOffsets(rocketParts)
    this.components = {}  // { stage1, stage2, fairing, satellite, boosters: [] }
    this.leaders = {}     // { stage1: Entity, stage2: Entity, ... }
  }

  /**
   * 组装火箭 — 为每个部件创建 leader + component
   * @param {Object} posHolders  { stage1: {prop}, stage2: {prop}, fairing: {prop}, satellite: {prop} }
   * @param {Object} orientProps { stage1: orientProp, stage2: ..., fairing: ..., satellite: ... }
   * @returns {Object} leaders { stage1, stage2, fairing, satellite }
   */
  assemble(posHolders, orientProps) {
    const findPart = (cat) => this.rocketParts.find(p => p.category === cat)

    // ── 一级 ──
    const stage1Part = findPart('stage1')
    if (stage1Part) {
      const leader = this.viewer.entities.add({
        position: posHolders.stage1.prop,
        orientation: orientProps.stage1,
      })
      this.leaders.stage1 = leader
      this.components.stage1 = new FirstStage({
        viewer: this.viewer,
        posHolder: posHolders.stage1,
        orientProp: orientProps.stage1,
        config: stage1Part,
        zOffsets: this.zOffsets,
      })
      this.components.stage1.build()
    }

    // ── 二级 ──
    const stage2Part = findPart('stage2')
    if (stage2Part) {
      const leader = this.viewer.entities.add({
        position: posHolders.stage2.prop,
        orientation: orientProps.stage2,
      })
      this.leaders.stage2 = leader
      this.components.stage2 = new SecondStage({
        viewer: this.viewer,
        posHolder: posHolders.stage2,
        orientProp: orientProps.stage2,
        config: stage2Part,
        zOffsets: this.zOffsets,
      })
      this.components.stage2.build()
    }

    // ── 整流罩 ──
    const fairingPart = findPart('fairing')
    if (fairingPart) {
      const leader = this.viewer.entities.add({
        position: posHolders.fairing.prop,
        orientation: orientProps.fairing,
      })
      this.leaders.fairing = leader
      this.components.fairing = new Fairing({
        viewer: this.viewer,
        posHolder: posHolders.fairing,
        orientProp: orientProps.fairing,
        config: fairingPart,
        zOffsets: this.zOffsets,
      })
      this.components.fairing.build()
    }

    // ── 载荷 ──
    const satPart = findPart('satellite')
    if (satPart) {
      const leader = this.viewer.entities.add({
        position: posHolders.satellite.prop,
      })
      this.leaders.satellite = leader
      this.components.satellite = new Payload({
        viewer: this.viewer,
        posHolder: posHolders.satellite,
        orientProp: orientProps.satellite,
        config: satPart,
        zOffsets: this.zOffsets,
      })
      this.components.satellite.build()
    }

    // ── 助推器 (侧挂于一级) ──
    const boosterParts = this.rocketParts.filter(p => p.category === 'booster')
    if (boosterParts.length > 0 && this.components.stage1) {
      this.components.boosters = []
      const stage1Radius = this.components.stage1.dimensions.bodyRadius
      const stage1BodyZ = this.zOffsets.stage1Body
      const stage1BodyLen = this.components.stage1.dimensions.bodyLength
      const zBase = stage1BodyZ  // 一级主体中心

      boosterParts.forEach((bp, i) => {
        const angle = (i / boosterParts.length) * Math.PI * 2
        const booster = new Booster({
          viewer: this.viewer,
          posHolder: posHolders.booster,  // 独立 posHolder，不跟随一级分离
          orientProp: orientProps.stage1,
          config: bp,
          zOffsets: this.zOffsets,
          sideAngle: angle,
          parentRadius: stage1Radius,
          zBase,
        })
        booster.build()
        this.components.boosters.push(booster)
      })
    }

    return this.leaders
  }

  /** 获取组件 */
  getComponent(name) { return this.components[name] }

  /** 获取 leader 实体 */
  getLeader(name) { return this.leaders[name] }

  /** 分离某个组件 */
  separate(name, time, fallPosProp) {
    const comp = this.components[name]
    const leader = this.leaders[name]
    if (!comp || !leader) return

    comp.freezeOrientation(time)
    comp.switchPosition(fallPosProp)
    leader.position = fallPosProp
    comp._frozenOrient = null  // 由组件内部管理
    // 重新冻结 (switchPosition 后需要重新设置 leader orientation)
    const orient = comp.orientProp.getValue(time)
    if (orient) leader.orientation = new Cesium.ConstantProperty(orient)
  }

  /** 重置所有组件 */
  reset(posHolders, orientProps) {
    ;['stage1', 'stage2', 'fairing'].forEach(name => {
      const comp = this.components[name]
      const leader = this.leaders[name]
      if (comp && leader) {
        comp.restoreOrientation()
        comp.switchPosition(posHolders[name].prop)
        leader.position = posHolders[name].prop
        leader.orientation = orientProps[name]
      }
    })
    // 重置助推器
    if (this.components.boosters) {
      this.components.boosters.forEach(b => {
        b.restoreOrientation()
        b.switchPosition(posHolders.stage1.prop)
      })
    }
    // 重置载荷
    if (this.components.satellite) {
      this.components.satellite.retractPanels()
      this.components.satellite.hideBody()
    }
  }

  /** 销毁所有 */
  destroyAll() {
    Object.values(this.components).forEach(comp => {
      if (Array.isArray(comp)) {
        comp.forEach(c => c.destroy())
      } else if (comp) {
        comp.destroy()
      }
    })
  }
}

