export function createLaunchPad(viewer, lon, lat) {
  const pos = Cesium.Cartesian3.fromDegrees(lon, lat, 0)
  const enuMat = Cesium.Transforms.eastNorthUpToFixedFrame(pos)
  const orientQuat = Cesium.Quaternion.fromRotationMatrix(
    Cesium.Matrix4.getRotation(enuMat, new Cesium.Matrix3()), new Cesium.Quaternion()
  )

  function childPos(dx, dy, dz) {
    const off = new Cesium.Cartesian3(dx, dy, dz)
    const rot = Cesium.Matrix3.fromQuaternion(orientQuat, new Cesium.Matrix3())
    const worldOff = Cesium.Matrix3.multiplyByVector(rot, off, new Cesium.Cartesian3())
    return Cesium.Cartesian3.add(pos, worldOff, new Cesium.Cartesian3())
  }

  const parts = []

  parts.push(viewer.entities.add({
    position: childPos(0, 0, 5), orientation: orientQuat,
    cylinder: { length: 10, topRadius: 10, bottomRadius: 14, material: Cesium.Color.fromCssColorString('#5a5a66'), outline: false, slices: 48 },
  }))
  parts.push(viewer.entities.add({
    position: childPos(0, 0, 12), orientation: orientQuat,
    cylinder: { length: 4, topRadius: 8, bottomRadius: 10, material: Cesium.Color.fromCssColorString('#666672'), outline: false, slices: 48 },
  }))

  for (let i = 0; i < 4; i++) {
    const ang = i * Math.PI / 2 + Math.PI / 4
    const x = Math.cos(ang) * 9
    const y = Math.sin(ang) * 9
    parts.push(viewer.entities.add({
      position: childPos(x, y, 22), orientation: orientQuat,
      cylinder: { length: 40, topRadius: 0.8, bottomRadius: 0.8, material: Cesium.Color.fromCssColorString('#888892'), outline: false, slices: 16 },
    }))
    parts.push(viewer.entities.add({
      position: childPos(x * 0.6, y * 0.6, 30), orientation: orientQuat,
      box: { dimensions: new Cesium.Cartesian3(Math.abs(x) * 0.8 + 2, Math.abs(y) * 0.8 + 2, 1), material: Cesium.Color.fromCssColorString('#777780'), outline: false },
    }))
    parts.push(viewer.entities.add({
      position: childPos(x * 0.6, y * 0.6, 42), orientation: orientQuat,
      box: { dimensions: new Cesium.Cartesian3(Math.abs(x) * 0.8 + 2, Math.abs(y) * 0.8 + 2, 1), material: Cesium.Color.fromCssColorString('#777780'), outline: false },
    }))
  }

  return parts
}

