/**
 * html弹窗
 *
 * @export
 * @class HtmlPopup
 */
export default class HtmlPopup {
  constructor(options) {
    this._viewer = options.viewer;

    this._popupDiv = null;

    this._popupSite = options.popupSite ?? "center";

    this._parentDom = options.parentDom ?? document.body;

    this._position = options.position ?? new Cesium.Cartesian3();

    this._popupHtml = options.popupHtml ??
      `<div style="padding: 30px; background: #23aaf2;">HtmlPopup</div>`;

    this._init();
  }

  _init() {
    this._popupDiv = this._createPopupDiv();
  }

  _createPopupDiv() {
    const popupDiv = document.createElement(`div`);
    return popupDiv;
  }

  _preRenderEvent() {
    try {
      // 更新内部html
      this._popupDiv.innerHTML = this._popupHtml;

      // 更新场景位置
      const pointPosiiton = this._position;
      const camera = this._viewer.camera;
      const scene = this._viewer.scene;
      const cameraPosiiton = camera.position;

      // 实时计算弹窗和相机距离
      const distance = Cesium.Cartesian3.distance(
        pointPosiiton,
        camera.position
      );

      // 实时计算弹窗是否遮挡;
      const visible = new Cesium.EllipsoidalOccluder(
        Cesium.Ellipsoid.WGS84,
        cameraPosiiton
      ).isPointVisible(pointPosiiton);

      // 实时计算弹窗的窗口坐标
      const windowCoordinates = Cesium.SceneTransforms.worldToWindowCoordinates(
        scene,
        pointPosiiton
      );

      // 判断是否更改弹窗位置
      if (windowCoordinates && this._popupDiv) {
        const translate = { x: 0, y: 0 };
        if (this._popupSite == "center") {
          translate.x = Math.round(
            windowCoordinates.x - this._popupDiv.offsetWidth * 0.5
          );
          translate.y = Math.round(
            windowCoordinates.y - this._popupDiv.offsetHeight
          );
        }
        if (this._popupSite == "left") {
          translate.x = Math.round(
            windowCoordinates.x - this._popupDiv.offsetWidth * 0.0
          );
          translate.y = Math.round(
            windowCoordinates.y - this._popupDiv.offsetHeight
          );
        }
        if (this._popupSite == "right") {
          translate.x = Math.round(
            windowCoordinates.x - this._popupDiv.offsetWidth * 1.0
          );
          translate.y = Math.round(
            windowCoordinates.y - this._popupDiv.offsetHeight
          );
        }
        this._popupDiv.style.cssText = `
        box-sizing:border-box;
        position:absolute;
        pointer-events:none;
        left:${translate.x - 0}px;
        top:${translate.y - 40}px;`;
        this._popupDiv.style.visibility = "visible";
      } else {
        this._popupDiv.style.visibility = "hidden";
      }
    } catch (error) {
      throw error;
    }
  }

  open() {
    if (!this._parentDom.contains(this._popupDiv)) {
      this._parentDom.appendChild(this._popupDiv);
      // 绑定渲染事件
      this._viewer.scene.preRender.addEventListener(this._preRenderEvent, this);
    }
  }

  close() {
    if (this._parentDom.contains(this._popupDiv)) {
      this._parentDom.removeChild(this._popupDiv);
      // 解绑渲染事件
      this._viewer.scene.preRender.removeEventListener(
        this._preRenderEvent,
        this
      );
    }
  }

  set position(position) {
    this._position = position;
  }
  get position() {
    return this._position;
  }

  set popupHtml(popupHtml) {
    this._popupHtml = popupHtml;
  }
  get popupHtml() {
    return this._popupHtml;
  }
}

