// 根据类别获取部件列表
export function getPartsByCategory(category) {
  return PARTS_CATALOG.filter(p => p.category === category)
}

// 根据ID获取部件
export function getPartById(id) {
  return PARTS_CATALOG.find(p => p.id === id)
}

// 验证火箭配置是否合法
export function validateRocket(rocketParts) {
  const errors = []
  const categories = rocketParts.map(p => p.category)

  if (!categories.includes(PART_CATEGORIES.FAIRING)) {
    errors.push('缺少整流罩')
  }
  if (!categories.includes(PART_CATEGORIES.SATELLITE)) {
    errors.push('缺少卫星载荷')
  }
  if (!categories.includes(PART_CATEGORIES.STAGE1)) {
    errors.push('缺少一级火箭')
  }

  return { valid: errors.length === 0, errors }
}

/**
 * GPU 粒子系统
 * 基于 Cesium DrawCommand + 自定义 GLSL Shader
 * 粒子位置/大小/颜色全部在 GPU 顶点着色器中基于时间计算
 * CPU 每帧仅更新 uTime uniform，可渲染数千粒子
 */

const Cesium = window.Cesium

const defaultValue = (value, fallback) => (value !== undefined ? value : fallback)

export default class GPUParticlePrimitive {
  constructor(options) {
    this._destroyed = false
    this._context = null
    this._command = null

    this._show = defaultValue(options.show, true)
    this._time = 0.0
    this._globalOpacity = defaultValue(options.globalOpacity, 1.0)
    this._modelMatrix = defaultValue(options.modelMatrix, Cesium.Matrix4.clone(Cesium.Matrix4.IDENTITY))

    // 发射器配置
    this._particleCount = defaultValue(options.particleCount, 500)
    this._emitterPos = defaultValue(options.emitterPosition, [0, 0, 0])
    this._emitterRadius = defaultValue(options.emitterRadius, 2.0)
    this._direction = defaultValue(options.direction, [0, 0, -1])
    this._speed = defaultValue(options.speed, 50.0)
    this._speedVar = defaultValue(options.speedVariance, 20.0)
    this._spreadAngle = defaultValue(options.spreadAngle, 10.0) // 度

    // 生命周期 & 尺寸
    this._minLife = defaultValue(options.minLife, 0.3)
    this._maxLife = defaultValue(options.maxLife, 1.0)
    this._minSize = defaultValue(options.minSize, 5.0)
    this._maxSize = defaultValue(options.maxSize, 15.0)
    this._sizeGrowth = defaultValue(options.sizeGrowth, 1.0)

    // 颜色 & 物理
    this._startColor = defaultValue(options.startColor, [1.0, 0.9, 0.3])
    this._mid1Color  = defaultValue(options.mid1Color, [1.0, 0.5, 0.1])
    this._mid2Color  = defaultValue(options.mid2Color, [0.8, 0.2, 0.0])
    this._endColor   = defaultValue(options.endColor, [1.0, 0.1, 0.0])
    this._gravity = defaultValue(options.gravity, [0, 0, 0])
    this._drag = defaultValue(options.drag, 0.0)
    this._turbulence = defaultValue(options.turbulence, 0.3)
    this._additive = defaultValue(options.additive, true)
    this._smokeMode = defaultValue(options.smokeMode, false)

    // 预计算 uniform 值
    this._gravityC3 = new Cesium.Cartesian3(this._gravity[0], this._gravity[1], this._gravity[2])
    this._colorStartC3 = new Cesium.Cartesian3(this._startColor[0], this._startColor[1], this._startColor[2])
    this._colorMid1C3  = new Cesium.Cartesian3(this._mid1Color[0], this._mid1Color[1], this._mid1Color[2])
    this._colorMid2C3  = new Cesium.Cartesian3(this._mid2Color[0], this._mid2Color[1], this._mid2Color[2])
    this._colorEndC3   = new Cesium.Cartesian3(this._endColor[0], this._endColor[1], this._endColor[2])

    // 生成粒子初始数据
    this._generateParticles()
  }

  // ─── 生成粒子初始数据（CPU 一次性计算）───
  _generateParticles() {
    const n = this._particleCount
    const positions = new Float32Array(n * 3)
    const velocities = new Float32Array(n * 3)
    const lifetimes = new Float32Array(n)
    const sizes = new Float32Array(n)
    const startTimes = new Float32Array(n)
    const seeds = new Float32Array(n)

    // 归一化方向向量
    const dir = this._direction
    const dLen = Math.sqrt(dir[0] ** 2 + dir[1] ** 2 + dir[2] ** 2) || 1
    const dx = dir[0] / dLen, dy = dir[1] / dLen, dz = dir[2] / dLen

    // 构建垂直基向量（用于锥形发射）
    let px, py, pz
    if (Math.abs(dz) < 0.99) {
      px = dy; py = -dx; pz = 0
    } else {
      px = 1; py = 0; pz = 0
    }
    const pLen = Math.sqrt(px * px + py * py + pz * pz) || 1
    px /= pLen; py /= pLen; pz /= pLen
    // q = dir × p
    const qx = dy * pz - dz * py
    const qy = dz * px - dx * pz
    const qz = dx * py - dy * px

    const spreadRad = Cesium.Math.toRadians(this._spreadAngle)

    for (let i = 0; i < n; i++) {
      // 随机发射位置（圆形面内）
      const a = Math.random() * Math.PI * 2
      const r = Math.sqrt(Math.random()) * this._emitterRadius
      positions[i * 3] = this._emitterPos[0] + Math.cos(a) * r
      positions[i * 3 + 1] = this._emitterPos[1] + Math.sin(a) * r
      positions[i * 3 + 2] = this._emitterPos[2]

      // 锥形随机速度
      const speed = this._speed + (Math.random() - 0.5) * 2 * this._speedVar
      const theta = Math.random() * spreadRad
      const phi = Math.random() * Math.PI * 2
      const cosT = Math.cos(theta), sinT = Math.sin(theta)
      const cosp = Math.cos(phi), sinp = Math.sin(phi)

      velocities[i * 3] = (dx * cosT + (px * cosp + qx * sinp) * sinT) * speed
      velocities[i * 3 + 1] = (dy * cosT + (py * cosp + qy * sinp) * sinT) * speed
      velocities[i * 3 + 2] = (dz * cosT + (pz * cosp + qz * sinp) * sinT) * speed

      // 随机生命周期 & 尺寸
      lifetimes[i] = this._minLife + Math.random() * (this._maxLife - this._minLife)
      sizes[i] = this._minSize + Math.random() * (this._maxSize - this._minSize)

      // 随机时间偏移（使粒子连续发射）
      startTimes[i] = Math.random() * this._maxLife

      // 随机种子（用于 shader 中每粒子独立噪声）
      seeds[i] = Math.random() * 1000.0
    }

    this._data = { positions, velocities, lifetimes, sizes, startTimes, seeds }
  }

  // ─── 创建 DrawCommand（含自定义 Shader）───
  _createCommand(context) {
    const { positions, velocities, lifetimes, sizes, startTimes, seeds } = this._data
    const n = this._particleCount

    const geometry = new Cesium.Geometry({
      attributes: {
        position: new Cesium.GeometryAttribute({
          componentDatatype: Cesium.ComponentDatatype.FLOAT,
          componentsPerAttribute: 3,
          values: positions,
        }),
        velocity: new Cesium.GeometryAttribute({
          componentDatatype: Cesium.ComponentDatatype.FLOAT,
          componentsPerAttribute: 3,
          values: velocities,
        }),
        lifetime: new Cesium.GeometryAttribute({
          componentDatatype: Cesium.ComponentDatatype.FLOAT,
          componentsPerAttribute: 1,
          values: lifetimes,
        }),
        psize: new Cesium.GeometryAttribute({
          componentDatatype: Cesium.ComponentDatatype.FLOAT,
          componentsPerAttribute: 1,
          values: sizes,
        }),
        startTime: new Cesium.GeometryAttribute({
          componentDatatype: Cesium.ComponentDatatype.FLOAT,
          componentsPerAttribute: 1,
          values: startTimes,
        }),
        seed: new Cesium.GeometryAttribute({
          componentDatatype: Cesium.ComponentDatatype.FLOAT,
          componentsPerAttribute: 1,
          values: seeds,
        }),
      },
      indices: new Uint16Array(Array.from({ length: n }, (_, i) => i)),
      primitiveType: Cesium.PrimitiveType.POINTS,
      boundingSphere: new Cesium.BoundingSphere(
        new Cesium.Cartesian3(this._emitterPos[0], this._emitterPos[1], this._emitterPos[2]),
        100000
      ),
    })

    const attributeLocations = Cesium.GeometryPipeline.createAttributeLocations(geometry)

    const vertexArray = Cesium.VertexArray.fromGeometry({
      geometry: geometry,
      context: context,
      attributeLocations: attributeLocations,
    })

    const shaderProgram = Cesium.ShaderProgram.fromCache({
      context: context,
      vertexShaderSource: `
        in vec3 position;
        in vec3 velocity;
        in float lifetime;
        in float psize;
        in float startTime;
        in float seed;

        uniform float uTime;
        uniform vec3  uGravity;
        uniform float uDrag;
        uniform float uSizeGrowth;
        uniform float uSmokeMode;

        out float vAge01;
        out float vSeed;
        out float vSmokeMode;

        // 简易 hash 噪声
        float hash(float n) { return fract(sin(n) * 43758.5453); }

        // 多层 sin 湍流（烟雾用，比单层更自然）
        vec3 smokeTurbulence(float age, float seed, float strength) {
          float t = age * 1.5;
          float h1 = hash(seed) * 6.28;
          float h2 = hash(seed + 7.3) * 6.28;
          float h3 = hash(seed + 13.7) * 6.28;
          // 低频大范围 + 中频细节
          vec3 turb;
          turb.x = sin(t * 0.8 + h1) * 0.6 + sin(t * 2.1 + h2) * 0.3;
          turb.y = cos(t * 1.1 + h2) * 0.6 + cos(t * 1.7 + h3) * 0.3;
          turb.z = sin(t * 0.6 + h3) * 0.6 + sin(t * 1.9 + h1) * 0.3;
          return turb * strength;
        }

        void main() {
          float age = mod(uTime + startTime, lifetime);
          vAge01 = age / lifetime;
          vSeed = seed;
          vSmokeMode = uSmokeMode;

          // 基础位移
          vec3 displacement = velocity * age + uGravity * age * age * 0.5;

          // 阻力衰减
          float dragFactor = exp(-uDrag * age);
          displacement *= dragFactor;

          if (uSmokeMode > 0.5) {
            // 烟雾：低速有机翻滚湍流，随年龄增强
            float turbStrength = (1.0 - dragFactor) * 15.0 * smoothstep(0.0, 0.3, vAge01);
            displacement += smokeTurbulence(age, seed, turbStrength);
          } else {
            // 火焰：高速随机抖动
            float turbStrength = (1.0 - dragFactor) * 8.0;
            float t = age * 3.0;
            displacement.x += sin(t + hash(seed) * 6.28) * turbStrength * hash(seed);
            displacement.y += cos(t * 1.3 + hash(seed + 1.0) * 6.28) * turbStrength * hash(seed + 1.0);
            displacement.z += sin(t * 0.7 + hash(seed + 2.0) * 6.28) * turbStrength * hash(seed + 2.0);
          }

          vec3 pos = position + displacement;
          vec4 viewPos = czm_modelView * vec4(pos, 1.0);
          gl_Position = czm_projection * viewPos;

          float sizeFade = 1.0 - smoothstep(0.7, 1.0, vAge01);

          if (uSmokeMode > 0.5) {
            // 烟雾：稳定缓慢增长，无闪烁
            float currentSize = psize * (1.0 + vAge01 * uSizeGrowth);
            gl_PointSize = max(1.0, currentSize * sizeFade * (300.0 / max(1.0, -viewPos.z)));
          } else {
            // 火焰：高频闪烁
            float flicker = 0.8 + 0.2 * sin(uTime * 15.0 + seed * 10.0);
            float currentSize = psize * (1.0 + vAge01 * uSizeGrowth) * flicker;
            gl_PointSize = max(1.0, currentSize * sizeFade * (300.0 / max(1.0, -viewPos.z)));
          }
        }
      `,
      fragmentShaderSource: `
        in float vAge01;
        in float vSeed;
        in float vSmokeMode;

        uniform vec3  uColorStart;
        uniform vec3  uColorMid1;
        uniform vec3  uColorMid2;
        uniform vec3  uColorEnd;
        uniform float uGlobalOpacity;
        uniform float uTurbulence;
        uniform float uTime;

        // 2D hash & value noise
        float hash21(vec2 p) {
          p = fract(p * vec2(443.897, 441.423));
          p += dot(p, p.yx + 19.19);
          return fract((p.x + p.y) * p.x);
        }
        float noise2D(vec2 p) {
          vec2 i = floor(p);
          vec2 f = fract(p);
          f = f * f * (3.0 - 2.0 * f);
          float a = hash21(i);
          float b = hash21(i + vec2(1, 0));
          float c = hash21(i + vec2(0, 1));
          float d = hash21(i + vec2(1, 1));
          return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
        }
        // fbm 分形噪声（烟雾体积感）
        float fbm(vec2 p) {
          float v = 0.0;
          float a = 0.5;
          for (int i = 0; i < 4; i++) {
            v += a * noise2D(p);
            p *= 2.0;
            a *= 0.5;
          }
          return v;
        }

        void main() {
          vec2 coord = gl_PointCoord - vec2(0.5);

          if (vSmokeMode > 0.5) {
            // ═══ 烟雾模式 ═══
            // 低频噪声扭曲坐标（有机翻滚边缘）
            float n1 = fbm(coord * 4.0 + vec2(vSeed, uTime * 0.15));
            float n2 = fbm(coord * 7.0 + vec2(vSeed + 10.0, uTime * 0.1));
            vec2 distortedCoord = coord + (n1 - 0.5) * uTurbulence + (n2 - 0.5) * uTurbulence * 0.3;

            float dist = length(distortedCoord);
            if (dist > 0.5) discard;

            // 软边缘：更柔和的渐变
            float alpha = 1.0 - smoothstep(0.15, 0.5, dist);

            // fbm 密度调制：模拟烟团体积感
            float density = fbm(coord * 5.0 + vec2(vSeed * 0.3, uTime * 0.08));
            density = mix(0.3, 1.0, density);
            alpha *= density;

            // 颜色渐变
            vec3 color;
            if (vAge01 < 0.33) {
              color = mix(uColorStart, uColorMid1, vAge01 / 0.33);
            } else if (vAge01 < 0.66) {
              color = mix(uColorMid1, uColorMid2, (vAge01 - 0.33) / 0.33);
            } else {
              color = mix(uColorMid2, uColorEnd, (vAge01 - 0.66) / 0.34);
            }

            // 烟雾不增亮，轻微暗化边缘
            float edgeDarken = mix(0.7, 1.0, 1.0 - dist * 1.5);
            color *= edgeDarken;

            // 生命淡出：前 15% 淡入，后 60% 淡出
            float lifeFade = smoothstep(0.0, 0.15, vAge01) * (1.0 - smoothstep(0.4, 1.0, vAge01));

            out_FragColor = vec4(color, alpha * lifeFade * uGlobalOpacity * 0.9);
          } else {
            // ═══ 火焰模式 ═══
            float n1 = noise2D(coord * 8.0 + vec2(vSeed, uTime * 0.5));
            float n2 = noise2D(coord * 12.0 + vec2(vSeed + 10.0, uTime * 0.3));
            vec2 distortedCoord = coord + (n1 - 0.5) * uTurbulence + (n2 - 0.5) * uTurbulence * 0.5;

            float dist = length(distortedCoord);
            if (dist > 0.5) discard;

            float alpha = 1.0 - smoothstep(0.2, 0.5, dist);
            float density = noise2D(coord * 6.0 + vec2(vSeed * 0.1, uTime * 0.2));
            alpha *= 0.5 + 0.5 * density;
            alpha = clamp(alpha, 0.0, 1.0);

            vec3 color;
            if (vAge01 < 0.33) {
              color = mix(uColorStart, uColorMid1, vAge01 / 0.33);
            } else if (vAge01 < 0.66) {
              color = mix(uColorMid1, uColorMid2, (vAge01 - 0.33) / 0.33);
            } else {
              color = mix(uColorMid2, uColorEnd, (vAge01 - 0.66) / 0.34);
            }

            float lifeFade = 1.0 - smoothstep(0.5, 1.0, vAge01);
            float coreBoost = 1.0 + (1.0 - dist * 2.0) * 0.4;
            color *= coreBoost;

            out_FragColor = vec4(color, alpha * lifeFade * uGlobalOpacity);
          }
        }
      `,
      attributeLocations: attributeLocations,
    })

    const renderState = Cesium.RenderState.fromCache({
      depthTest: { enabled: true },
      depthMask: false,
      blending: this._additive
        ? Cesium.BlendingState.ADDITIVE_BLEND
        : Cesium.BlendingState.ALPHA_BLEND,
    })

    this._command = new Cesium.DrawCommand({
      vertexArray: vertexArray,
      shaderProgram: shaderProgram,
      uniformMap: {
        uTime: () => this._time,
        uGravity: () => this._gravityC3,
        uDrag: () => this._drag,
        uSizeGrowth: () => this._sizeGrowth,
        uColorStart: () => this._colorStartC3,
        uColorMid1: () => this._colorMid1C3,
        uColorMid2: () => this._colorMid2C3,
        uColorEnd: () => this._colorEndC3,
        uGlobalOpacity: () => this._globalOpacity,
        uTurbulence: () => this._turbulence,
        uSmokeMode: () => this._smokeMode ? 1.0 : 0.0,
      },
      renderState: renderState,
      pass: Cesium.Pass.TRANSLUCENT,
      primitiveType: Cesium.PrimitiveType.POINTS,
      modelMatrix: this._modelMatrix,
    })
  }

  // ─── 属性 ───
  get show() { return this._show }
  set show(v) { this._show = v }

  get time() { return this._time }
  set time(v) { this._time = v }

  get globalOpacity() { return this._globalOpacity }
  set globalOpacity(v) { this._globalOpacity = v }

  get modelMatrix() { return this._modelMatrix }
  set modelMatrix(v) { this._modelMatrix = v }

  // ─── Primitive 接口 ───
  update(frameState) {
    if (!this._show) return
    if (!this._command) this._createCommand(frameState.context)
    this._command.modelMatrix = this._modelMatrix
    frameState.commandList.push(this._command)
  }

  isDestroyed() { return this._destroyed }
  destroy() {
    this._destroyed = true
    return Cesium.destroyObject(this)
  }
}

/**
 * 预计算轨迹生成脚本（纯 Node.js，不依赖 Cesium）
 * 运行: node scripts/generateTrajectory.js
 * 输出: public/trajectory.json
 */

import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

// ─── 物理常量 ───
const EARTH_RADIUS = 6378137
const GM = 3.986004418e14
const TARGET_ORBIT_ALT = 400000
const ORBITAL_VELOCITY = Math.sqrt(GM / (EARTH_RADIUS + TARGET_ORBIT_ALT))
const LAUNCH_LON = 110.95
const LAUNCH_LAT = 19.61

// ─── 飞行阶段 ───
const FLIGHT_PHASES = [
  { name: '点火起飞', t0: 0,   t1: 10,  alt0: 200,    alt1: 600,     vel0: 0,    vel1: 150,              pitch0: 90, pitch1: 90 },
  { name: '垂直爬升', t0: 10,  t1: 60,  alt0: 500,    alt1: 25000,   vel0: 150,  vel1: 2500,             pitch0: 90, pitch1: 78 },
  { name: '重力转弯', t0: 60,  t1: 140, alt0: 25000,  alt1: 100000,  vel0: 2500, vel1: 5500,             pitch0: 78, pitch1: 30 },
  { name: '二级推进', t0: 140, t1: 280, alt0: 100000, alt1: 400000,  vel0: 5500, vel1: ORBITAL_VELOCITY, pitch0: 30, pitch1: 0  },
  { name: '轨道运行', t0: 280, t1: 560, alt0: 400000, alt1: 400000,  vel0: ORBITAL_VELOCITY, vel1: ORBITAL_VELOCITY, pitch0: 0,  pitch1: 0  },
]

const STAGE1_SEP_TIME = 140
const FAIRING_JETTISON_TIME = 200
const STAGE2_SEP_TIME = 280
const BOOSTER_SEP_TIME = 100
const TOTAL_FLIGHT_TIME = 560

// ─── 辅助函数 ───
function lerp(a, b, t) { return a + (b - a) * t }
function easeInOut(t) { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2 }
function toRad(deg) { return deg * Math.PI / 180 }
function toDeg(rad) { return rad * 180 / Math.PI }

function findPhase(t) {
  for (const p of FLIGHT_PHASES) {
    if (t >= p.t0 && t <= p.t1) return p
  }
  return FLIGHT_PHASES[FLIGHT_PHASES.length - 1]
}

function computeFlightParams(t) {
  const phase = findPhase(t)
  const frac = (t - phase.t0) / (phase.t1 - phase.t0)
  return {
    alt: lerp(phase.alt0, phase.alt1, easeInOut(frac)),
    vel: lerp(phase.vel0, phase.vel1, frac),
    pitch: lerp(phase.pitch0, phase.pitch1, frac),
    phaseName: phase.name,
  }
}

// ─── 生成主轨迹 ───
function generateMainTrajectory(dt = 1) {
  const points = []
  const orbitOmega = ORBITAL_VELOCITY / (EARTH_RADIUS + TARGET_ORBIT_ALT)
  let cumLon = LAUNCH_LON
  let cumLat = LAUNCH_LAT

  for (let t = 0; t <= TOTAL_FLIGHT_TIME; t += dt) {
    const p = computeFlightParams(t)
    const vH = p.vel * Math.cos(toRad(p.pitch))
    const dLon = (vH * dt) / (EARTH_RADIUS * Math.cos(toRad(cumLat))) * toDeg(1)
    cumLon += dLon

    if (t > STAGE2_SEP_TIME) {
      const orbitT = t - STAGE2_SEP_TIME
      cumLat = LAUNCH_LAT * Math.cos(orbitOmega * orbitT)
    }

    points.push({ time: t, lon: cumLon, lat: cumLat, alt: p.alt, vel: p.vel, pitch: p.pitch, phaseName: p.phaseName })
  }
  return points
}

// ─── 生成坠落轨迹（惯性+分离推力+大气阻力）───
function generateFallingTrajectory(sepTime, sepLon, sepLat, sepAlt, sepVel, sepPitch, duration = 120) {
  const points = []
  const dt = 1
  const vH0 = sepVel * Math.cos(toRad(sepPitch))
  const vV0 = sepVel * Math.sin(toRad(sepPitch))

  let lon = sepLon, lat = sepLat, alt = sepAlt
  let vH = vH0 * 0.7    // 保留70%惯性前向速度
  let vV = vV0          // 保持垂直速度

  for (let i = 0; i <= duration; i += dt) {
    points.push({ time: sepTime + i, lon, lat, alt: Math.max(0, alt) })

    // 分离推力：前3秒向后推（减速）
    if (i < 3) {
      vH -= vH0 * 0.1  // 每秒减少10%前向速度
    }

    // 重力
    vV -= 9.8 * dt

    // 大气阻力：高度越低阻力越大
    const altKm = alt / 1000
    const drag = altKm < 100 ? 0.02 : (altKm < 200 ? 0.01 : 0.005)
    vH *= (1 - drag)
    vV *= (1 - drag * 0.5)

    alt += vV * dt
    lon += (vH * dt) / (EARTH_RADIUS * Math.cos(toRad(lat))) * toDeg(1)

    if (alt <= 0) break
  }
  return points
}

// ─── lonLatAlt → ECEF（纯数学，不依赖 Cesium）───
function lonLatAltToECEF(lon, lat, alt) {
  const lonRad = toRad(lon), latRad = toRad(lat)
  const r = EARTH_RADIUS + alt
  return [
    r * Math.cos(latRad) * Math.cos(lonRad),
    r * Math.cos(latRad) * Math.sin(lonRad),
    r * Math.sin(latRad),
  ]
}

// ─── 向量运算 ───
function vecNormalize(v) {
  const len = Math.sqrt(v[0]**2 + v[1]**2 + v[2]**2) || 1
  return [v[0]/len, v[1]/len, v[2]/len]
}
function vecCross(a, b) {
  return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]
}

// ─── 计算卫星轨道 ECEF 坐标（罗德里格斯旋转）───
function computeOrbitECEF(deployLon, deployLat, deployAlt, duration) {
  const orbitRadius = EARTH_RADIUS + TARGET_ORBIT_ALT
  const omega = ORBITAL_VELOCITY / orbitRadius

  // 部署点 ECEF，缩放到轨道半径
  const deployPos = lonLatAltToECEF(deployLon, deployLat, deployAlt)
  const radial = vecNormalize(deployPos)
  const p0 = [radial[0]*orbitRadius, radial[1]*orbitRadius, radial[2]*orbitRadius]

  // 东向向量
  const lonRad = toRad(deployLon)
  const east = [-Math.sin(lonRad), Math.cos(lonRad), 0]

  // 轨道法向量 = p0 × east
  const n = vecNormalize(vecCross(p0, east))

  // n · p0
  const dotNP = n[0]*p0[0] + n[1]*p0[1] + n[2]*p0[2]

  // 罗德里格斯旋转: v' = v*cos(θ) + (n×v)*sin(θ) + n*(n·v)*(1-cos(θ))
  function rotate(theta) {
    const c = Math.cos(theta), s = Math.sin(theta)
    const crossNV = vecCross(n, p0)
    return [
      p0[0]*c + crossNV[0]*s + n[0]*dotNP*(1-c),
      p0[1]*c + crossNV[1]*s + n[1]*dotNP*(1-c),
      p0[2]*c + crossNV[2]*s + n[2]*dotNP*(1-c),
    ]
  }

  // 卫星轨道位置
  const positions = []
  for (let i = 0; i <= duration; i++) {
    const [x, y, z] = rotate(omega * i)
    positions.push({ time: STAGE2_SEP_TIME + i, x, y, z })
  }

  // 完整轨道路径（可视化）
  const period = 2 * Math.PI / omega
  const fullPath = []
  for (let i = 0; i <= period; i += 5) {
    fullPath.push(rotate(omega * i))
  }

  return { positions, fullPath }
}

// ─── 主函数 ───
function main() {
  console.log('正在预计算轨迹...')

  const mainTraj = generateMainTrajectory(1)
  console.log(`  主轨迹: ${mainTraj.length} 个采样点`)

  // 分离点数据
  const sepPt1 = mainTraj.find(p => Math.abs(p.time - STAGE1_SEP_TIME) <= 1)
  const sepPt2 = mainTraj.find(p => Math.abs(p.time - STAGE2_SEP_TIME) <= 1)
  const jetPt  = mainTraj.find(p => Math.abs(p.time - FAIRING_JETTISON_TIME) <= 1)
  const boostPt = mainTraj.find(p => Math.abs(p.time - BOOSTER_SEP_TIME) <= 1)

  // 坠落轨迹
  const stage1Fall = generateFallingTrajectory(STAGE1_SEP_TIME, sepPt1.lon, sepPt1.lat, sepPt1.alt, sepPt1.vel, sepPt1.pitch, 130)
  const stage2Fall = generateFallingTrajectory(STAGE2_SEP_TIME, sepPt2.lon, sepPt2.lat, sepPt2.alt, sepPt2.vel, sepPt2.pitch, 150)
  const fairingFall = generateFallingTrajectory(FAIRING_JETTISON_TIME, jetPt.lon, jetPt.lat, jetPt.alt, jetPt.vel, jetPt.pitch, 130)
  const boosterFall = generateFallingTrajectory(BOOSTER_SEP_TIME, boostPt.lon, boostPt.lat, boostPt.alt, boostPt.vel, boostPt.pitch, 100)
  console.log(`  一级坠落: ${stage1Fall.length} 点`)
  console.log(`  二级坠落: ${stage2Fall.length} 点`)
  console.log(`  整流罩坠落: ${fairingFall.length} 点`)
  console.log(`  助推器坠落: ${boosterFall.length} 点`)

  const orbitDuration = TOTAL_FLIGHT_TIME - STAGE2_SEP_TIME
  const { positions: satOrbit, fullPath: orbitPath } = computeOrbitECEF(sepPt2.lon, sepPt2.lat, sepPt2.alt, orbitDuration)
  console.log(`  卫星轨道: ${satOrbit.length} 点`)
  console.log(`  轨道路径: ${orbitPath.length} 点`)

  const data = {
    mainTrajectory: mainTraj,
    stage1Fall,
    stage2Fall,
    fairingFall,
    boosterFall,
    satelliteOrbit: satOrbit,
    orbitPath,
  }

  const outPath = path.resolve(__dirname, '../public/trajectory.json')
  fs.writeFileSync(outPath, JSON.stringify(data))
  const sizeKB = (fs.statSync(outPath).size / 1024).toFixed(1)
  console.log(`\n已生成: ${outPath} (${sizeKB} KB)`)
}

main()

