    { id: 'stage1_std', category: 'stage1', name: '标准一级', color: '#f0f0f0', dimensions: { bodyLength: 40, bodyRadius: 3.5, ringLength: 1.5, ringRadius: 3.6, engineLength: 6, engineTopR: 3.0, engineBotR: 1.0, nozzleLength: 3, nozzleTopR: 1.0, nozzleBotR: 0.6 } },
    { id: 'booster_std', category: 'booster', name: '标准助推器', color: '#aaaab0', dimensions: { bodyLength: 25, bodyRadius: 2.0, engineLength: 4, engineTopR: 1.5, engineBotR: 0.5, nozzleLength: 2, nozzleTopR: 0.5, nozzleBotR: 0.3 } },
    { id: 'booster_std', category: 'booster', name: '标准助推器', color: '#aaaab0', dimensions: { bodyLength: 25, bodyRadius: 2.0, engineLength: 4, engineTopR: 1.5, engineBotR: 0.5, nozzleLength: 2, nozzleTopR: 0.5, nozzleBotR: 0.3 } },
  ],
})

// 计算火箭总体性能
const rocketStats = computed(() => {
  if (state.rocketParts.length === 0) {
    return { totalMass: 0, totalThrust: 0, twr: 0, parts: 0 }
  }

  let totalMass = 0
  let totalThrust = 0

  state.rocketParts.forEach(part => {
    if (part.physics) {
      totalMass += part.physics.mass || 0
      totalThrust += part.physics.thrust || 0
    }
  })

  return {
    totalMass,
    totalThrust,
    twr: totalMass > 0 ? (totalThrust / (totalMass * 9.8)).toFixed(2) : 0,
    parts: state.rocketParts.length,
  }
})

const validation = computed(() => validateRocket(state.rocketParts))

export function useRocketStore() {
  function navigate(view) {
    state.currentView = view
  }

  function addPart(part) {
    state.rocketParts.push({ ...part })
  }

  function removePart(index) {
    state.rocketParts.splice(index, 1)
  }

  function movePart(fromIndex, toIndex) {
    if (toIndex < 0 || toIndex >= state.rocketParts.length) return
    const [part] = state.rocketParts.splice(fromIndex, 1)
    state.rocketParts.splice(toIndex, 0, part)
  }

  function clearRocket() {
    state.rocketParts = []
  }

  function useDefaultRocket() {
    state.rocketParts = JSON.parse(JSON.stringify(state.defaultRocket))
  }

  function confirmBuild() {
    if (validation.value.valid) {
      navigate('launch')
    }
  }

  return {
    state,
    rocketStats,
    validation,
    navigate,
    addPart,
    removePart,
    movePart,
    clearRocket,
    useDefaultRocket,
    confirmBuild,
  }
}

